/// Set the `VkResult` `command` returns; `false` for a command without one.
pub fn set_result(command: &mut Command<'_>, ret: i32) -> bool {
    match command {
        Command::QueueSubmit(a) => a.ret = ret,
        Command::QueueWaitIdle(a) => a.ret = ret,
        Command::DeviceWaitIdle(a) => a.ret = ret,
        Command::CreateFence(a) => a.ret = ret,
        Command::ResetFences(a) => a.ret = ret,
        Command::GetFenceStatus(a) => a.ret = ret,
        Command::WaitForFences(a) => a.ret = ret,
        Command::CreateEvent(a) => a.ret = ret,
        Command::GetEventStatus(a) => a.ret = ret,
        Command::SetEvent(a) => a.ret = ret,
        Command::ResetEvent(a) => a.ret = ret,
        Command::CreateQueryPool(a) => a.ret = ret,
        Command::GetQueryPoolResults(a) => a.ret = ret,
        Command::CreateShaderModule(a) => a.ret = ret,
        Command::CreatePipelineCache(a) => a.ret = ret,
        Command::GetPipelineCacheData(a) => a.ret = ret,
        Command::MergePipelineCaches(a) => a.ret = ret,
        Command::CreateGraphicsPipelines(a) => a.ret = ret,
        Command::CreateComputePipelines(a) => a.ret = ret,
        Command::CreatePipelineLayout(a) => a.ret = ret,
        Command::CreateSampler(a) => a.ret = ret,
        Command::CreateDescriptorSetLayout(a) => a.ret = ret,
        Command::CreateDescriptorPool(a) => a.ret = ret,
        Command::ResetDescriptorPool(a) => a.ret = ret,
        Command::AllocateDescriptorSets(a) => a.ret = ret,
        Command::FreeDescriptorSets(a) => a.ret = ret,
        Command::CreateFramebuffer(a) => a.ret = ret,
        Command::CreateRenderPass(a) => a.ret = ret,
        Command::ResetCommandPool(a) => a.ret = ret,
        Command::AllocateCommandBuffers(a) => a.ret = ret,
        Command::BeginCommandBuffer(a) => a.ret = ret,
        Command::EndCommandBuffer(a) => a.ret = ret,
        Command::ResetCommandBuffer(a) => a.ret = ret,
        Command::CreateDescriptorUpdateTemplate(a) => a.ret = ret,
        Command::CreateSamplerYcbcrConversion(a) => a.ret = ret,
        Command::CreateRenderPass2(a) => a.ret = ret,
        Command::CreatePrivateDataSlot(a) => a.ret = ret,
        Command::SetPrivateData(a) => a.ret = ret,
        Command::QueueSubmit2(a) => a.ret = ret,
        _ => return false,
    }
    true
}

