/// Every handle `command` creates, in order, and their type: the ids the guest
/// chose before the host call, the host's handles after it.
pub fn output_handles<'c>(command: &'c mut Command<'_>) -> Option<(Kind, Vec<&'c mut u64>)> {
    match command {
        Command::CreateFence(a) => Some((
            Kind::Fence,
            a.p_fence.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreateEvent(a) => Some((
            Kind::Event,
            a.p_event.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreateQueryPool(a) => Some((
            Kind::QueryPool,
            a.p_query_pool.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreateShaderModule(a) => Some((
            Kind::ShaderModule,
            a.p_shader_module.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreatePipelineCache(a) => Some((
            Kind::PipelineCache,
            a.p_pipeline_cache.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreateGraphicsPipelines(a) => Some((
            Kind::Pipeline,
            a.p_pipelines
                .iter_mut()
                .flatten()
                .map(|h| &mut h.0)
                .collect(),
        )),
        Command::CreateComputePipelines(a) => Some((
            Kind::Pipeline,
            a.p_pipelines
                .iter_mut()
                .flatten()
                .map(|h| &mut h.0)
                .collect(),
        )),
        Command::CreatePipelineLayout(a) => Some((
            Kind::PipelineLayout,
            a.p_pipeline_layout.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreateSampler(a) => Some((
            Kind::Sampler,
            a.p_sampler.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreateDescriptorSetLayout(a) => Some((
            Kind::DescriptorSetLayout,
            a.p_set_layout.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreateDescriptorPool(a) => Some((
            Kind::DescriptorPool,
            a.p_descriptor_pool.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::AllocateDescriptorSets(a) => Some((
            Kind::DescriptorSet,
            a.p_descriptor_sets
                .iter_mut()
                .flatten()
                .map(|h| &mut h.0)
                .collect(),
        )),
        Command::CreateFramebuffer(a) => Some((
            Kind::Framebuffer,
            a.p_framebuffer.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreateRenderPass(a) => Some((
            Kind::RenderPass,
            a.p_render_pass.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::AllocateCommandBuffers(a) => Some((
            Kind::CommandBuffer,
            a.p_command_buffers
                .iter_mut()
                .flatten()
                .map(|h| &mut h.0)
                .collect(),
        )),
        Command::CreateDescriptorUpdateTemplate(a) => Some((
            Kind::DescriptorUpdateTemplate,
            a.p_descriptor_update_template
                .iter_mut()
                .map(|h| &mut h.0)
                .collect(),
        )),
        Command::CreateSamplerYcbcrConversion(a) => Some((
            Kind::SamplerYcbcrConversion,
            a.p_ycbcr_conversion.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreateRenderPass2(a) => Some((
            Kind::RenderPass,
            a.p_render_pass.iter_mut().map(|h| &mut h.0).collect(),
        )),
        Command::CreatePrivateDataSlot(a) => Some((
            Kind::PrivateDataSlot,
            a.p_private_data_slot.iter_mut().map(|h| &mut h.0).collect(),
        )),
        _ => None,
    }
}

